// Generated branding assets for COZAM official documents
export const COZAM_LOGO_BASE64 = '';
export const JONATHA_SIGNATURE_BASE64 = '';

export function getCozamLogoBuffer(): Buffer {
  return Buffer.from(COZAM_LOGO_BASE64, 'base64');
}

export function getJonathaSignatureBuffer(): Buffer {
  return Buffer.from(JONATHA_SIGNATURE_BASE64, 'base64');
}
